INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 11, 'theory', 'Quiz: functional programming');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 0, 'Which of these functions is pure?', '["x => x + Math.random()", "(a, b) => a + b", "arr => arr.sort()", "() => Date.now()"]', 1, 'A pure function depends only on its arguments and changes nothing: sort() mutates the array in place, and the others read hidden state.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 1, 'Why does const not make an array immutable?', '["Because const only works on numbers", "Because arrays have no methods", "Because const is forbidden in modules", "const only forbids rebinding: the array contents can still be changed with push and other methods"]', 3, 'For immutability you create copies ([...a, x]) and use toSorted, with, map and filter, while Object.freeze helps catch accidental edits.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 2, 'What is the difference between compose(f, g) and pipe(g, f)?', '["None: both apply g first, then f; only the order of writing differs", "The results differ", "compose is asynchronous", "pipe only works with numbers"]', 0, 'compose is written right to left, as in math, and pipe is written left to right, the way we read text.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 3, 'What is a trampoline used for in recursion?', '["To make computations twice as fast", "To cache results", "To avoid growing the call stack: instead of a recursive call a step function is returned and a loop calls it", "To call functions in parallel"]', 2, 'Most engines have no tail call optimization, so deep recursion fails with RangeError; a trampoline turns it into a loop.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 4, 'What does the functor law «map(x => x) changes nothing» guarantee?', '["map always returns a number", "map always mutates the original array", "map runs lazily", "A transformation inside a container does not change its structure: the identity mapping returns an equivalent container"]', 3, 'Together with the second law (map of a composition equals the composition of maps) this lets you safely refactor chains of map.');
